/* NexTalk service worker.
 *
 * Deliberately hand-written rather than generated by next-pwa/workbox: this
 * app is auth-gated and realtime, so the caching rules need to be explicit
 * about what must never be stored. Bump CACHE_VERSION to invalidate
 * everything on the next deploy.
 */

const CACHE_VERSION = "v1";
const SHELL_CACHE = `nextalk-shell-${CACHE_VERSION}`;
const ASSET_CACHE = `nextalk-assets-${CACHE_VERSION}`;
const PAGE_CACHE = `nextalk-pages-${CACHE_VERSION}`;

const OFFLINE_URL = "/offline";

// Kept small on purpose. Everything else is cached lazily as it is used, so
// an install never downloads pages the user may not open.
const SHELL_ASSETS = [
  OFFLINE_URL,
  "/icons/icon-192.png",
  "/icons/icon-512.png",
  "/manifest.webmanifest",
];

// Anything matching these is never read from or written to a cache. Serving a
// stale message list or, worse, one user's data to the next person to sign in
// on a shared device is far worse than simply failing while offline.
function isNeverCacheable(url) {
  return (
    url.pathname.startsWith("/api/") ||
    url.pathname.startsWith("/auth/") ||
    url.pathname === "/login" ||
    url.pathname === "/signup" ||
    url.pathname === "/complete-profile"
  );
}

// Hashed build output and our own icons are content-addressed or stable, so
// they can be served cache-first without a staleness risk.
function isImmutableAsset(url) {
  return url.pathname.startsWith("/_next/static/") || url.pathname.startsWith("/icons/");
}

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches
      .open(SHELL_CACHE)
      // addAll is atomic: one 404 would reject the whole install and leave
      // the old worker in place, so add individually and tolerate misses.
      .then((cache) => Promise.allSettled(SHELL_ASSETS.map((u) => cache.add(u))))
      .then(() => self.skipWaiting())
  );
});

self.addEventListener("activate", (event) => {
  const keep = new Set([SHELL_CACHE, ASSET_CACHE, PAGE_CACHE]);
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((k) => !keep.has(k)).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

// Lets the page tell a waiting worker to take over immediately (see
// components/PWARegister.js), instead of waiting for every tab to close.
self.addEventListener("message", (event) => {
  if (event.data === "SKIP_WAITING") self.skipWaiting();
});

// Signing out must not leave the previous account's pages on disk.
self.addEventListener("message", (event) => {
  if (event.data === "CLEAR_CACHES") {
    event.waitUntil(caches.keys().then((keys) => Promise.all(keys.map((k) => caches.delete(k)))));
  }
});

self.addEventListener("fetch", (event) => {
  const { request } = event;

  if (request.method !== "GET") return;

  const url = new URL(request.url);

  // Cross-origin (Supabase, Cloudinary, fonts) is left entirely to the
  // browser. Supabase realtime and auth in particular must not be touched.
  if (url.origin !== self.location.origin) return;

  if (isNeverCacheable(url)) return;

  if (isImmutableAsset(url)) {
    event.respondWith(cacheFirst(request, ASSET_CACHE));
    return;
  }

  if (request.mode === "navigate") {
    event.respondWith(navigationHandler(request));
    return;
  }
});

async function cacheFirst(request, cacheName) {
  const cached = await caches.match(request);
  if (cached) return cached;

  const response = await fetch(request);
  if (response.ok) {
    const cache = await caches.open(cacheName);
    cache.put(request, response.clone());
  }
  return response;
}

// Network-first. A chat app should always prefer live content; the cache is
// only a fallback for a genuinely failed request, and /offline is the last
// resort so the user gets branded UI rather than the browser's error page.
async function navigationHandler(request) {
  try {
    const response = await fetch(request);
    if (response.ok) {
      const cache = await caches.open(PAGE_CACHE);
      cache.put(request, response.clone());
    }
    return response;
  } catch {
    const cached = await caches.match(request);
    if (cached) return cached;

    const offline = await caches.match(OFFLINE_URL);
    if (offline) return offline;

    return new Response("You are offline.", {
      status: 503,
      headers: { "Content-Type": "text/plain" },
    });
  }
}
